// เลือกคลิปที่จะโหลด — ปรับตัวเลขตรงนี้ได้
const PER_LANG = 12;          // คลิปที่ยอดวิวสูงสุดของแต่ละภาษา (ไทย / ลาว)
const MIN_PLAYS = 0;          // ตัดคลิปที่ยอดวิวต่ำกว่านี้ (0 = ไม่ตัด)
const j = $input.first().json;
const raw = typeof j.data === 'string' ? JSON.parse(j.data) : j;
const vids = (raw.videos || raw).filter(v => v.video_id && v.url && (v.plays || 0) >= MIN_PLAYS);
const picked = [];
for (const lang of ['thai', 'lao']) {
  vids.filter(v => v.language === lang).sort((a, b) => (b.plays || 0) - (a.plays || 0)).slice(0, PER_LANG).forEach(v => picked.push(v));
}
return picked.map(v => ({ json: { video_id: v.video_id, url: v.url, language: v.language, category: v.category, plays: v.plays, creator: v.creator } }));

// ผลของแต่ละคลิปที่สั่งโหลด (มาจากโหนด "สั่งเซิร์ฟเวอร์โหลดคลิป")
const items = $('สั่งเซิร์ฟเวอร์โหลดคลิป').all().map(i => i.json);
const bad = items.filter(i => !i.ok);
return [{ json: {
  total: items.length,
  newlyDownloaded: items.filter(i => i.status === 'downloaded').length,
  alreadyThere: items.filter(i => i.status === 'exists').length,
  failed: bad.length,
  firstErrors: bad.map(b => String(b.error || b.message || JSON.stringify(b)).slice(0, 250)).slice(0, 3)
} }];
